import Foundation

// Classifier fixture debs, each built by real dpkg-deb so the tests
// exercise genuine ar/tar/xz structure. Binary payload files contain
// valid Mach-O / fat / ELF headers (and one real ELF executable) so the
// classifier's magic-number sniffing runs against realistic bytes.

/// Base64 of a dpkg-deb fixture: iOS app package: /Applications/Hello.app with a thin arm64 executable, a framework dylib, Info.plist and an icon.
private let fixtureAppStandardBase64 = ""

/// Base64 of a dpkg-deb fixture: iOS app whose .app bundle hides in a nonstandard location (Library/Custom/Spot.app).
private let fixtureAppNonstandardBase64 = ""

/// Base64 of a dpkg-deb fixture: Rootless-era app under var/jb/Applications/RL.app with a thin arm64 executable.
private let fixtureAppRootlessBase64 = ""

/// Base64 of a dpkg-deb fixture: Rootful-era app whose executable is a fat binary containing an arm64 MH_EXECUTE slice (arch iphoneos-arm).
private let fixtureAppFatBase64 = ""

/// Base64 of a dpkg-deb fixture: Substrate tweak: MobileSubstrate dylib + filter plist, no .app bundle.
private let fixtureTweakBase64 = ""

/// Base64 of a dpkg-deb fixture: Theme pack (arch all): plists and fake pngs only, no binary content.
private let fixtureThemeBase64 = ""

/// Base64 of a dpkg-deb fixture: Desktop Linux deb (amd64) shipping a real ELF binary in usr/bin.
private let fixtureNonIOSBase64 = ""

/// Base64 of a dpkg-deb fixture: App bundle with no native executable at all (arch all): not launchable, so not convertible.
private let fixtureAppNoBinaryBase64 = ""

/// Classifier fixture debs.
enum ClassifierFixtures {
    static var appStandard: Data { decode(fixtureAppStandardBase64, "appStandard") }
    static var appNonstandard: Data { decode(fixtureAppNonstandardBase64, "appNonstandard") }
    static var appRootless: Data { decode(fixtureAppRootlessBase64, "appRootless") }
    static var appFat: Data { decode(fixtureAppFatBase64, "appFat") }
    static var tweak: Data { decode(fixtureTweakBase64, "tweak") }
    static var theme: Data { decode(fixtureThemeBase64, "theme") }
    static var nonIOS: Data { decode(fixtureNonIOSBase64, "nonIOS") }
    static var appNoBinary: Data { decode(fixtureAppNoBinaryBase64, "appNoBinary") }

    private static func decode(_ base64: String, _ name: String) -> Data {
        guard let d = Data(base64Encoded: base64) else {
            fatalError("corrupt classifier fixture: " + name)
        }
        return d
    }
}
